 for(let j=0;j<H;j++){let s=P.b2[j];for(let i=0;i<H;i++)s+=h1[i]*P.W2[i*H+j];h2[j]=s>0?s:0;}
 for(let j=0;j<NO;j++){let s=P.b3[j];for(let i=0;i<H;i++)s+=h2[i]*P.W3[i*NO+j];o[j]=s;}
