     const d2=new Float32Array(H); for(let i=0;i<H;i++){let s=0;for(let j=0;j<NO;j++){if(!d3[j])continue;G.W3[i*NO+j]+=f.h2[i]*d3[j];s+=P.W3[i*NO+j]*d3[j];}d2[i]=f.h2[i]>0?s:0;} for(let j=0;j<NO;j++)G.b3[j]+=d3[j];
